func:
let d = msg.payload;

// Verificar campos obligatorios
if (!d || !d.paciente_id || d.frecuencia_cardiaca === undefined || d.spo2 === undefined) {
    msg.statusCode = 400;
    msg.payload = {
        estado: "ERROR",
        codigo: 400,
        mensaje: "Estructura JSON inválida para signos vitales"
    };
    return msg;
}

// Clasificación clínica
let alerta = "NINGUNA";
if (d.spo2 < 90) {
    alerta = "CRITICA_DESATURACION";
} else if (d.frecuencia_cardiaca > 100) {
    alerta = "TAQUICARDIA";
}

// Guardar última muestra en contexto
flow.set("ultimo_registro_esp32", d);

// Respuesta de éxito al microcontrolador
msg.statusCode = 201;
msg.payload = {
    estado: "REGISTRADO",
    codigo: 201,
    alerta_clinica: alerta,
    servidor_timestamp: new Date().toISOString()
};

return msg;
